"use client";
/* Echo, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Echo(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("echo"); }, []);
  return React.createElement("piix-pal", { "pal": "echo", ...piixAttrs(props) });
}

export default Echo;
